mod solution;

fn main() {
    let cases = [
    (r#"n=5 adds=(1,5),(3,2),(4,4) query=3"#, r#"7"#),
    (r#"n=4 adds=(1,3),(2,4),(4,8) query=4"#, r#"15"#),
    (r#"
n=4 adds=(1,3),(2,4),(4,8) query=4
"#, r#"15"#),
    (r#"  
n=5 adds=(1,5),(3,2),(4,4) query=3
  "#, r#"7"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS fenwick-tree");
}
